int main(int argc, char** argv) {
  // create a socket
  int sock = socket(AF_INET, SOCK_STREAM, 0);
  if (sock < 0) {
    perror("socket");
    exit(1);
  }

  // bind the socket to a port
  struct sockaddr_in addr;
  memset(&addr, 0, sizeof(addr));
  addr.sin_family = AF_INET;
  addr.sin_addr.s_addr = htonl(INADDR_ANY);
  addr.sin_port = htons(8080);
  if (bind(sock, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
    perror("bind");
    exit(1);
  }

  // listen for connections
  if (listen(sock, 10) < 0) {
    perror("listen");
    exit(1);
  }

  // accept connections
  while (1) {
    struct sockaddr_in client_addr;
    socklen_t client_addr_len = sizeof(client_addr);
    int client_sock = accept(sock, (struct sockaddr*)&client_addr, &client_addr_len);
    if (client_sock < 0) {
      perror("accept");
      exit(1);
    }

    // read the request
    char request_buf[1024];
    int request_len = read(client_sock, request_buf, 1024);
    if (request_len < 0) {
      perror("read");
      exit(1);
    }

    // parse the request
    char method[1024];
    char url[1024];
    char version[1024];
    sscanf(request_buf, "%s %s %s", method, url, version);

    // create a file for the response
    FILE* response = fdopen(dup(client_sock), "w");
    if (response == NULL) {
      perror("fdopen");
      exit(1);
    }

    // call the appropriate function based on the URL
    if (strcmp(url, "/hello") == 0) {
      http_hello_page(url, method, request_buf, response);
    } else {
      fprintf(response, "HTTP/1.1 404 Not Found\r\n");
      fprintf(response, "Content-Type: text/html\r\n");
      fprintf(response, "Content-Length: 0\r\n");
      fprintf(response, "\r\n");
    }

    // close the response file
    fclose(response);
  }

  // close the socket
  close(sock);

  return 0;
}

